INSERT INTO "rules" VALUES('R1','Primary merge limit','Primary schools at or below this enrolment can merge.','primary_merge_max',5.0,'students','HP proposal, June 2025','https://www.tribuneindia.com/news/himachal/100-schools-to-be-shut-400-merged-in-himachal-proposal-forwarded');
INSERT INTO "rules" VALUES('R2','Merge radius','The receiving school must be within this straight-line distance.','merge_radius_km',2.0,'km','HP proposal, June 2025','https://www.tribuneindia.com/news/himachal/100-schools-to-be-shut-400-merged-in-himachal-proposal-forwarded');
