INSERT INTO "rules" VALUES('R4','Walk limit, Classes 1 to 5','A school within this walking distance.','walk_limit_primary_km',1.0,'km','RTE Rules 2010, Rule 6(1)','https://indiankanoon.org/doc/42884596/');
INSERT INTO "rules" VALUES('R5','Walk limit, Classes 6 to 8','A school within this walking distance.','walk_limit_upper_km',3.0,'km','RTE Rules 2010, Rule 6(1)','https://indiankanoon.org/doc/42884596/');
INSERT INTO "rules" VALUES('R6','Transport or escort','Per child per year for children beyond the limit or on unsafe routes.','transport_per_child',6000.0,'Rs','RTE Rule 6(4); Samagra Shiksha; HP PAB 2025-26','https://dsel.education.gov.in/sites/default/files/pab/hp2526.pdf');
